import { get_s3_files_download } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    rowInfo: Object,
    viewFootfolderDetails: Boolean
  },
  data() {
    return {
      FileUrl: "",
      loading: false
    };
  },
  watch: {
    viewFootfolderDetails: {
      async handler() {
        if (this.viewFootfolderDetails == true) {
          const data = this.$store.getters.GetUserObj;
          this.get_fileurl(data);
        }
      },
      immediate: true
    }
  },
  // watch: {
  //     viewFootfolderDetails(newVal) {
  //         if (newVal) {
  //             const data = this.$store.getters.GetUserObj;
  //             this.get_fileurl(data);
  //         } else {
  //             this.FileUrl = '';
  //             this.loading = false;
  //         }
  //     },
  // },
  methods: {
    closeDialog() {
      this.FileUrl = "";
      this.loading = false;
      this.$emit("clicked", 0);
    },
    async get_fileurl(data) {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(get_s3_files_download, {
          input: {
            organization_id: data.organization.organization_id,
            key: this.rowInfo.Key
          }
        }));
        var response = JSON.parse(result.data.get_s3_files_download);
        this.FileUrl = response.data;
        this.loading = false;
      } catch (error) {
        this.loading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
